<section class="page-hero shell compact"><p class="kicker">DesignOS · Room Planner</p><h1>Create a room.</h1><p>Use actual internal dimensions in centimetres. This first planner works as a measured 2D planning board rather than an approximate decorative moodboard.</p></section>
<section class="section section-tight shell"><form method="post" class="commerce-form room-create-form"><?=csrf_field()?><div class="two-col"><label>Room name<input name="name" required maxlength="80" value="<?=e($room['name']??'')?>" placeholder="e.g. Main living room"></label><label>Room type<select name="room_type"><?php foreach(designos_rooms() as $key=>$label):?><option value="<?=e($key)?>" <?=($room['room_type']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Width (cm)<input type="number" name="width_cm" min="180" max="1500" value="<?=e((string)($room['width_cm']??360))?>" required></label><label>Length (cm)<input type="number" name="length_cm" min="180" max="2000" value="<?=e((string)($room['length_cm']??480))?>" required></label><label>Ceiling height (cm)<input type="number" name="ceiling_cm" min="210" max="600" value="<?=e((string)($room['ceiling_cm']??270))?>" required></label><label>Indicative room budget<input type="number" name="budget" min="0" step="500" value="<?=e((string)($room['budget']??20000))?>"></label><label>Wall colour<input name="wall_color" maxlength="60" value="<?=e($room['wall_color']??'Warm ivory')?>"></label><label>Floor material<input name="floor_material" maxlength="60" value="<?=e($room['floor_material']??'Natural stone / tile')?>"></label><label class="span-2">Style profile<select name="style_profile_guid"><option value="">No saved profile yet</option><?php foreach($styles as $sp):?><option value="<?=e($sp['guid'])?>"><?=e($sp['label'])?> · <?=e($sp['result']['profile_name'])?></option><?php endforeach;?></select><small>Run the <a href="<?=e(url('/style-finder'))?>">Style Finder</a> first if you want recommendations to follow a saved direction.</small></label></div><div class="inline-actions"><button class="btn primary" type="submit">Create room plan</button><a class="btn outline" href="<?=e(url('/account/rooms'))?>">Cancel</a></div></form></section>
